"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8715],{58715:a=>{a.exports=JSON.parse('{"slug":"aramco-skidka-aziya-g7-rezervy-neft","locale":"zh","title":"沙特对亚洲折价创6年新高，俄罗斯维持高于市场的油价更难","description":"Aramco对亚洲每桶折价$5，为2020年以来最大；G7将释放100百万桶储备。分析其对俄罗斯石油与卢布的影响。","blocks":[{"id":"b001","kind":"paragraph","text":"沙特Aramco将旗舰原油Arab Light面向亚洲买家的2026年十一月售价定为比当地基准低$5/桶，十月折价为$2。这是2020年六月以来最大折价，而交易商和炼厂此前预期涨价。但沙特石油并未因此变便宜：折价相对交易基准计算，Brent仍高于$100。对欧洲，Aramco反而把十一月价格提高$3，未解释原因。"},{"id":"b002","kind":"paragraph","text":"这就是官方销售价格的运作方式。Aramco大多通过长期合同售油，每月公布每桶相对交易基准的溢价或折价。类似批发商价目表：商品不变，折扣决定买家流向。亚洲降价有两个解释。霍尔木兹海峡油流恢复，JPMorgan估计中东出口已回到战前约98%。另一方面，运输变贵：波斯湾到中国的大型油轮日租约$1.2百万，而一年前仅$80千，折价部分补偿买家的运费。"},{"id":"b003","kind":"paragraph","text":"与此同时，G7各国在十月2日同意从战略储备释放100百万桶原油和柴油。大部分柴油将在前20天释放，其余在4个月内完成。十月5日上午Brent约$101.6/桶，较周五下降0.65%，但价格仍高于$100。"},{"id":"b004","kind":"paragraph","text":"俄罗斯最关注亚洲市场。2026年九月，Urals在中国的到港价比世界价格高约$15/桶，在印度高$3.7。这类加价称为溢价，八月几乎不存在。溢价包含运抵买家港口的成本，而海运费用大涨。此前波斯湾供应不足，中印炼厂寻找替代，推高溢价。如今海湾供应恢复，主要竞争者又向同一批买家降价，维持溢价更难。降了多少要看十月价格。用于矿产开采税计算的九月Urals月均价为$92.08/桶，八月为$67.11；这一价格决定石油企业向预算缴纳多少税款。"},{"id":"b005","kind":"paragraph","text":"对普通人，这并非直接讲汽油。俄罗斯加油站价格受到燃料出口禁令支撑，更取决于本国炼厂运行。传导渠道不同：石油收入减少意味着预算税收和市场外汇供给减少，从而压低卢布。仅因沙特一次降价就买外汇，是押注尚未实现的传导链。也不应认为九月油价已保护卢布：Aramco十二月是否继续折价、霍尔木兹是否保持开放，仍未知。"},{"id":"b006","kind":"heading","text":"沙特为何下调对亚洲的原油价格？"},{"id":"b007","kind":"paragraph","text":"霍尔木兹海峡运输恢复，产油商必须争夺买家。同时运费上涨：运往中国的大型油轮日租约$1.2百万，折价部分补偿运输。对欧洲，Aramco反而把十一月价格上调$3。"},{"id":"b008","kind":"heading","text":"G7将从储备释放多少石油？"},{"id":"b009","kind":"paragraph","text":"100百万桶原油与柴油。大部分柴油将在前20天释放，其余在4个月内完成。"},{"id":"b010","kind":"heading","text":"沙特折价如何影响俄罗斯？"},{"id":"b011","kind":"paragraph","text":"通过亚洲的俄罗斯石油售价。九月Urals在中国比世界价高约$15/桶，在印度高$3.7，因为波斯湾原油不足。如今海湾供应恢复，沙特对亚洲降价，维持这些溢价更难。收入减少意味着税收和外汇供给减少。"}],"sources":[{"label":"沙特意外下调十一月对亚洲油价，创6年低点","url":"https://gulfbusiness.com/en/2026/saudi-arabia/saudi-aramco-cuts-asia-oil-prices-six-year-low/"},{"label":"沙特旗舰原油对亚洲售价降至六年低点","url":"https://finance.yahoo.com/energy/articles/saudis-cut-flagship-oil-price-010940614.html"},{"label":"中东原油出口回升、G7释放储备，油价下滑","url":"https://finance.yahoo.com/energy/articles/oil-slips-middle-east-crude-013514252.html"},{"label":"油价飙升后，G7同意释放100百万桶原油和柴油","url":"https://www.bnnbloomberg.ca/markets/oil/2026/10/02/g7-nations-agree-to-release-100-million-barrels-of-oil-including-diesel-a-boost-for-trump/"},{"label":"九月Urals在波罗的海、印度和中国涨价，ESPO由折价转为溢价","url":"https://www.interfax.ru/business/1119753"},{"label":"中东供应不足推高印度港口的Urals溢价","url":"https://ru.themoscowtimes.com/2026/09/15/premii-na-neft-urals-vzleteli-v-portakh-indii-iz-za-defitsita-predlozheniya-blizhnevostochnogo-syrya-treydery-a206168"},{"label":"2026年八月Urals原油平均价格","url":"https://www.garant.ru/hotlaw/federal/2228866/"},{"label":"俄罗斯政府延长所有市场参与者的柴油出口禁令","url":"https://neftegaz.ru/news/gosreg/937606-pravitelstvo-rf-prodlilo-zapret-na-eksport-diztopliva-dlya-vsekh-uchastnikov-rynka/"}],"sourceBodySha256":"d0bdb602832d24f0790aba072f3c026c358e4bc824f142b052def8b14bac6284"}')}}]);